namespace ModMon.Cli;

internal static class AgentGuidanceTemplates
{
	public const string OwnershipMarker =
		"<!-- Generated by ModMon. Do not edit this file manually. -->";

	private const string ResourcePrefix = "ModMon.GuidanceTemplates.";
	private const string ProjectNameToken = "{{projectName}}";
	private const string ProjectNameLowerToken = "{{projectNameLower}}";

	public static string Agents(string projectName)
	{
		return Load("AGENTS.md", projectName);
	}

	public static string Skill(string projectName)
	{
		return Load("SKILL.md", projectName);
	}

	public static string Architecture(string projectName)
	{
		return Load("architecture-patterns.md", projectName);
	}

	public static string QuickReference(string projectName)
	{
		return Load("quick-reference.md", projectName);
	}

	private static string Load(string fileName, string projectName)
	{
		var resourceName = ResourcePrefix + fileName;
		var assembly = typeof(AgentGuidanceTemplates).Assembly;
		using var stream = assembly.GetManifestResourceStream(resourceName)
			?? throw new InvalidOperationException(
				$"Embedded guidance template '{resourceName}' was not found.");
		using var reader = new StreamReader(stream);
		return reader.ReadToEnd()
			.Replace(ProjectNameLowerToken, projectName.ToLowerInvariant())
			.Replace(ProjectNameToken, projectName);
	}
}
